api_traffic.request_body:
{"query":"{
        globalFilter(entitiesListSize: 50){
          entitiesData {
            entity {
                id
                label
                typeOfEntity
            } count
          }
          typeOfEntityData {
            type
            count
          }
          itemsPagination {
            totalCount
            items {
              thumbnail
              item {
                id
                label
                fields
                {
                  ...
                  on KeyValueField {
                    key
                    value
                  }
                }
                breadcrumbs {
                  label
                  link
                }
                relatedTypesOfEntity {
                  type
                  count
                }
              }
            }
          }
        }
        }"}

{"query":"{
      search(searchParameters: { totalCount: 0 gallery: false facets: [{ id: "query" type: "value" },{ id: "query-all" type: "value" data: [{ value: "1" label: "Cerca in tutti i campi delle schede" }] },{ id: "query-links" type: "value" },{ id: "entity-types" type: "value" operator: "OR" limit: 10 order: "count" },{ id: "entity-search" type: "value" },{ id: "entity-links" type: "value" searchData: ["entity-type"] }] page: { offset: 0 limit: 10 } results: { order: { type: "score" key: "_score" direction: "DESC" } fields: [{ id: "description" highlight: true limit: 200 }] } filters: [{ facetId: "query" value: "corsari" searchIn: [{ key: "label.ngrams" operator: "LIKE" }] },{ facetId: "query-all" value: null searchIn: [{ key: "label.ngrams^5,text^4,fields.*^3" operator: "=" }] },{ facetId: "query-links" value: [] searchIn: [{ key: "source.entityType" operator: "=" }] },{ facetId: "entity-links" value: [] searchIn: [{ key: "relatedEntities.id" operator: "=" }] pagination: { limit: 50 offset: 0 } }] }){
        facets {
          id
          type
          operator
          limit
          order
          totalCount
          data {
            label
            value
            counter
            searchData {
              key
              value
            }
          }
        }
      }
    }"}

{"query":"{
      search(searchParameters: { totalCount: 0 gallery: false facets: [{ id: "query" type: "value" },{ id: "query-all" type: "value" data: [{ value: "1" label: "Cerca in tutti i campi delle schede" }] },{ id: "query-links" type: "value" },{ id: "entity-types" type: "value" operator: "OR" limit: 10 order: "count" },{ id: "entity-search" type: "value" },{ id: "entity-links" type: "value" searchData: ["entity-type"] }] page: { offset: 0 limit: 10 } results: { order: { type: "score" key: "_score" direction: "DESC" } fields: [{ id: "description" highlight: true limit: 200 }] } filters: [{ facetId: "query" value: "corsari" searchIn: [{ key: "label.ngrams" operator: "LIKE" }] },{ facetId: "query-all" value: null searchIn: [{ key: "label.ngrams^5,text^4,fields.*^3" operator: "=" }] },{ facetId: "query-links" value: [] searchIn: [{ key: "source.entityType" operator: "=" }] },{ facetId: "entity-links" value: [] searchIn: [{ key: "relatedEntities.id" operator: "=" }] pagination: { limit: 50 offset: 0 } }] }){
        totalCount
        results {
          order{
            type
            key
            direction
          }
          fields
          {
            id
            highlight
            limit
          }
          items {
            ... on Entity {
              id
              label
              typeOfEntity
              fields {
                ...
                on KeyValueField {
                  key
                  value
                }
                ... on KeyValueFieldGroup {
                  label
                  fields {
                    ...
                    on KeyValueField {
                      key
                      value
                    }
                  }
                }
              }
              relatedEntities {
                  count
                  entity{
                    id
                    label
                    typeOfEntity
                    relation
                  }
              }
              relatedItems {
                  thumbnail
                  item {
                    label
                    id
                    fields {
                      ...
                      on KeyValueField {
                        key
                        value
                      }
                      ... on KeyValueFieldGroup {
                        label
                        fields {
                          ...
                          on KeyValueField {
                            key
                            value
                          }
                        }
                      }
                    }
                }
                relatedTypesOfEntity {
                  type
                  count
                }
              }
            }
            ... on Item {
              id
              label
              icon
              title
              subTitle
              image
              text
              relatedTypesOfEntity {
                type
                count
              }
              breadcrumbs {
                label
                link
              }
              fields {
                ...
                on KeyValueField {
                  key
                  value
                }
                ... on KeyValueFieldGroup {
                  label
                  fields {
                    ...
                    on KeyValueField {
                      key
                      value
                    }
                  }
                }
              }
            }
          }
        }
      }
    }"}
